const oldTree = {
  type: "div",
  props: { id: "app", className: "a" },
  children: [
    { type: "h1", props: {}, children: [{ type: "TEXT", props: { value: "Hello" } }] },
    { type: "p", props: {}, children: [{ type: "TEXT", props: { value: "old" } }] },
  ],
};

const newTree = {
  type: "div",
  props: { id: "app", className: "b" },
  children: [
    { type: "h1", props: {}, children: [{ type: "TEXT", props: { value: "Hello!" } }] },
    { type: "span", props: {}, children: [{ type: "TEXT", props: { value: "new" } }] },
  ],
};

const ops = [];

function diff(oldNode, newNode, path) {
  if (oldNode.type !== newNode.type) {
    ops.push(`REPLACE ${path}: <${oldNode.type}> -> <${newNode.type}> (subtree remounted)`);
    return;
  }
  const oldProps = oldNode.props || {};
  const newProps = newNode.props || {};
  const keys = new Set([...Object.keys(oldProps), ...Object.keys(newProps)]);
  for (const key of keys) {
    if (oldProps[key] !== newProps[key]) {
      ops.push(`UPDATE_PROPS ${path}: ${key}: ${JSON.stringify(oldProps[key])} -> ${JSON.stringify(newProps[key])}`);
    }
  }
  const oldKids = oldNode.children || [];
  const newKids = newNode.children || [];
  const n = Math.max(oldKids.length, newKids.length);
  for (let i = 0; i < n; i++) {
    const childPath = `${path}/${i}`;
    if (i >= oldKids.length) {
      ops.push(`INSERT ${childPath}: <${newKids[i].type}>`);
    } else if (i >= newKids.length) {
      ops.push(`REMOVE ${childPath}: <${oldKids[i].type}>`);
    } else {
      diff(oldKids[i], newKids[i], childPath);
    }
  }
}

diff(oldTree, newTree, "root");
console.log(ops.join("\n"));

