const items = [
  { id: "a", label: "Alpha" },
  { id: "b", label: "Beta" },
  { id: "c", label: "Gamma" },
];

function render(items, keyFn, prev) {
  const instances = new Map();
  const rows = items.map((item, i) => {
    const key = keyFn(item, i);
    let inst = prev.get(key);
    if (!inst) inst = { checked: false };
    instances.set(key, inst);
    return `${item.label}[${inst.checked ? "x" : " "}]`;
  });
  return { rows, instances };
}

function demo(label, keyFn) {
  console.log(`--- ${label} ---`);
  let { rows, instances } = render(items, keyFn, new Map());
  // user checks "Beta": flip the instance currently rendering Beta
  const betaIdx = items.findIndex((it) => it.label === "Beta");
  instances.get(keyFn(items[betaIdx], betaIdx)).checked = true;
  ({ rows, instances } = render(items, keyFn, instances));
  console.log("before reorder: " + rows.join(", "));
  const reordered = [items[2], items[0], items[1]]; // Gamma, Alpha, Beta
  ({ rows } = render(reordered, keyFn, instances));
  console.log("after reorder (Gamma, Alpha, Beta): " + rows.join(", "));
}

demo("index keys", (item, i) => i);
console.log("BUG: the check moved from Beta to Alpha — state followed position, not the item");
demo("stable id keys", (item) => item.id);
console.log("OK: the check stayed with Beta — state followed the item");

