const scenarios = [
  { n: 1, desc: "<div> -> <span> at the same position", verdict: "REMOUNT", reason: "different element type, React tears down the whole subtree" },
  { n: 2, desc: "<Counter count={1} /> -> <Counter count={2} />", verdict: "PRESERVE", reason: "same type at same position, React updates props and keeps state" },
  { n: 3, desc: "{editing ? <EditForm/> : <Preview/>} toggled", verdict: "REMOUNT", reason: "the two branches are different types, so each toggle destroys and recreates state" },
  { n: 4, desc: "{show ? <Panel/> : null} toggled off and on", verdict: "REMOUNT", reason: "null unmounts Panel; coming back is a fresh mount, state is lost" },
  { n: 5, desc: "list reorder with stable keys", verdict: "PRESERVE", reason: "keys tell React the items are the same, it moves the DOM nodes and keeps state" },
  { n: 6, desc: "<div key=\"a\"> -> <div key=\"b\">", verdict: "REMOUNT", reason: "a changed key means a new identity, even though the type is identical" },
];

for (const s of scenarios) {
  console.log(`${s.n}. ${s.desc}`);
  console.log(`   PREDICT: ${s.verdict} — ${s.reason}`);
}

