function diffKeyed(oldKeys, newKeys) {
  const ops = [];
  const oldIndex = new Map();
  oldKeys.forEach((k, i) => oldIndex.set(k, i));
  const newSet = new Set(newKeys);
  for (const k of oldKeys) {
    if (!newSet.has(k)) ops.push(`REMOVE key=${k}`);
  }
  let lastPlaced = -1;
  for (const k of newKeys) {
    if (!oldIndex.has(k)) {
      ops.push(`INSERT key=${k}`);
      continue;
    }
    const oi = oldIndex.get(k);
    if (oi < lastPlaced) {
      ops.push(`MOVE key=${k} (from index ${oi})`);
    } else {
      lastPlaced = oi;
    }
  }
  return ops;
}

console.log(diffKeyed(["a", "b", "c", "d"], ["b", "a", "d", "c", "e"]).join("\n"));
console.log(diffKeyed(["a", "b", "c"], ["c", "a"]).join("\n"));

